WITH Hierarchy AS ( SELECT jijumcd, jijumname, jijumclcd FROM syep1000t WHERE jijumcd = #{jijumcd} UNION ALL SELECT j.jijumcd, j.jijumname, j.jijumclcd FROM syep1000t j INNER JOIN Hierarchy h ON j.jijumclcd = h.jijumcd ) INSERT INTO pppo7000t (clcd, jijumcd, coid, ntnid, upddate, updpn) SELECT c.clcd, h.jijumcd, #{coid}, #{ntnid}, GETDATE(), #{updpn} FROM Hierarchy h CROSS JOIN (
SELECT #{c} AS clcd
) AS c

